mapper.select:
SELECT contract_id AS contractId, member_id AS memberId, order_id AS orderId, product_id AS productId, monthly_fee AS monthlyFee, duration, contract_type AS contractType, contract_status AS contractStatus, start_date AS startDate, end_date AS endDate FROM contract
AND contract_id = #{keyword}
AND member_id = #{keyword}
ORDER BY start_date DESC

mapper.update:
UPDATE contract
SET contract_status = #{status}
WHERE contract_id = #{contractId}

mapper.insert:
INSERT INTO contract (
    member_id, order_id, product_id, monthly_fee, duration, 
    contract_type, contract_status, start_date, end_date
) VALUES (
    #{memberId}, #{orderId}, #{productId}, #{monthlyFee}, #{duration}, 
    #{contractType}, #{contractStatus}, #{startDate}, #{endDate}
)
